"use client";

import { useState } from "react";
import Link from "next/link";
import BootSequence from "./boot";
import type { NourChunk } from "@/lib/nour-path";
import { ICONS, projects } from "../lib/data";

export default function HomeClient({
  nChunks,
  restChunks,
  oPath,
  oEaseSamples,
  nourViewBox,
  nourStrokeWidth,
}: {
  nChunks: NourChunk[];
  restChunks: NourChunk[];
  oPath: string;
  oEaseSamples: number[];
  nourViewBox: string;
  nourStrokeWidth: number;
}) {
  const [booted, setBooted] = useState(false);

  return (
    <>
      {!booted && (
        <BootSequence
          nChunks={nChunks}
          restChunks={restChunks}
          oPath={oPath}
          oEaseSamples={oEaseSamples}
          nourViewBox={nourViewBox}
          nourStrokeWidth={nourStrokeWidth}
          onComplete={() => setBooted(true)}
        />
      )}

      <main
        className="mx-auto flex h-full max-w-4xl flex-col justify-center gap-6 overflow-hidden px-6 py-24"
        style={{ opacity: booted ? 1 : 0, transition: "opacity 0.6s ease" }}
        aria-hidden={!booted}
      >
        {Object.values(projects).map((project) => (
          <Link
            key={project.id}
            href={`/${project.id}`}
            className="group flex items-center gap-5 rounded-2xl p-6 transition-colors"
            style={{ backgroundColor: project.color }}
          >
            <span
              className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full"
              style={{ color: project.accent }}
            >
              {ICONS[project.id]}
            </span>
            <span className="flex flex-col">
              <span
                className="text-xs uppercase tracking-widest"
                style={{ color: project.accent }}
              >
                {project.tag}
              </span>
              <span className="text-2xl font-semibold text-white">
                {project.title}
              </span>
              <span className="text-sm text-white/70">{project.short}</span>
            </span>
          </Link>
        ))}
      </main>
    </>
  );
}